"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import { cn } from "@/lib/utils";
import { useState } from "react";
import { useSimulation } from "@/components/SimulationProvider";

import {
    LayoutDashboard,
    FileText,
    Store,
    Megaphone,
    Users,
    DollarSign,
    BarChart,
    Settings as SettingsIcon,
    ShieldCheck,
    X,
    LogOut,
    ChevronRight,
    Search
} from "lucide-react";

interface NavItem {
    label: string;
    href: string;
    icon: any;
}

const navItems: NavItem[] = [
    { label: "Painel", href: "/", icon: LayoutDashboard },
    { label: "Certificados", href: "/certificados", icon: FileText },
    { label: "Links de Venda", href: "/loja", icon: Store },
    { label: "Campanhas / Cupons", href: "/campanhas", icon: Megaphone },
    { label: "Clientes", href: "/clientes", icon: Users },
    { label: "Financeiro", href: "/financeiro", icon: DollarSign },
    { label: "Relatórios", href: "/relatorios", icon: BarChart },
    { label: "Configurações", href: "/configuracoes", icon: SettingsIcon },
];

export default function Sidebar() {
    const pathname = usePathname();
    const [isOpen, setIsOpen] = useState(false);
    const { currentUser, toggleRole } = useSimulation();

    const toggleSidebar = () => setIsOpen(!isOpen);

    const renderAvatarContent = () => {
        if (currentUser.avatar) {
            return (
                <div
                    className="size-9 rounded-full bg-slate-200 bg-cover bg-center border border-white shadow-sm flex-shrink-0"
                    style={{ backgroundImage: `url('${currentUser.avatar}')` }}
                />
            );
        }
        const initials = currentUser.name.split(' ').map((n: string) => n[0]).join('').substring(0, 2).toUpperCase();
        return (
            <div className="size-9 bg-primary/20 rounded-full flex items-center justify-center text-primary font-bold text-xs border border-white shadow-sm flex-shrink-0">
                {initials}
            </div>
        );
    };

    return (
        <>
            <aside
                className={cn(
                    "w-72 bg-background-dark text-white flex flex-col h-screen transition-all duration-500 border-r border-white/5 shadow-2xl",
                    isOpen ? "translate-x-0" : "-translate-x-full lg:translate-x-0",
                    !isOpen && "lg:w-72"
                )}
            >
                <div className="p-8 flex items-center justify-between mb-4">
                    <div className="flex items-center gap-4">
                        <div className="size-11 bg-primary text-white rounded-xl flex items-center justify-center shadow-lg shadow-primary/20">
                            <ShieldCheck size={24} />
                        </div>
                        <div className="leading-tight">
                            <h1 className="text-white text-xl font-black tracking-tighter">Delta</h1>
                            <p className="text-[10px] text-white/40 font-bold uppercase tracking-[0.2em]">Estrategista</p>
                        </div>
                    </div>
                    <button onClick={toggleSidebar} className="lg:hidden p-2 text-white/40 hover:bg-white/10 rounded-full transition-colors">
                        <X size={20} />
                    </button>
                </div>

                <nav className="flex-1 px-4 space-y-1.5 overflow-y-auto custom-scrollbar">
                    {navItems.map((item) => {
                        const isActive = pathname === item.href;
                        const Icon = item.icon;
                        return (
                            <Link
                                key={item.href}
                                href={item.href}
                                className={cn(
                                    "flex items-center gap-3.5 px-6 py-4 rounded-2xl transition-all duration-300 group",
                                    isActive
                                        ? "bg-primary text-white shadow-lg shadow-primary/30"
                                        : "text-white/40 hover:text-white hover:bg-white/5"
                                )}
                            >
                                <Icon size={22} className={cn(
                                    "transition-colors",
                                    isActive ? "text-white" : "text-white/30 group-hover:text-white"
                                )} />
                                <span className="text-[13px] font-bold tracking-tight">{item.label}</span>
                            </Link>
                        );
                    })}

                    {currentUser.role === 'admin' && (
                        <div className="mt-8 pt-8 border-t border-white/5">
                            <p className="px-6 mb-4 text-[10px] font-black text-white/20 uppercase tracking-[0.3em]">Administração</p>
                            <div className="space-y-1.5">
                                {[
                                    { label: "Gestão de Usuários", href: "/admin?tab=usuarios", icon: Users },
                                    { label: "Catálogo de Produtos", href: "/admin?tab=produtos", icon: FileText },
                                    { label: "Monitor de Vendas", href: "/admin?tab=vendas", icon: BarChart },
                                    { label: "Resgates Financeiros", href: "/admin?tab=financeiro", icon: DollarSign },
                                    { label: "Metas & Selos", href: "/admin?tab=metas", icon: ShieldCheck },
                                ].map((item) => {
                                    const isActive = pathname === "/admin" && (typeof window !== 'undefined' ? new URLSearchParams(window.location.search).get('tab') === item.href.split('=')[1] : false);
                                    const Icon = item.icon;
                                    return (
                                        <Link
                                            key={item.href}
                                            href={item.href}
                                            className={cn(
                                                "flex items-center gap-3.5 px-6 py-4 rounded-2xl transition-all duration-300 group",
                                                isActive
                                                    ? "bg-white/10 text-white"
                                                    : "text-white/30 hover:text-white hover:bg-white/5"
                                            )}
                                        >
                                            <Icon size={20} className={cn(
                                                "transition-colors",
                                                isActive ? "text-primary" : "text-white/20 group-hover:text-primary"
                                            )} />
                                            <span className="text-[12px] font-bold tracking-tight">{item.label}</span>
                                        </Link>
                                    );
                                })}
                            </div>
                        </div>
                    )}
                </nav>

                <div className="p-6 space-y-6 mt-auto">
                    {/* Role Switcher */}
                    <button
                        onClick={toggleRole}
                        className="w-full flex items-center justify-center gap-3 bg-white/5 hover:bg-white/10 text-white/60 py-4 rounded-3xl text-[10px] font-black uppercase tracking-[0.2em] transition-all border border-white/5"
                    >
                        <BarChart size={16} />
                        Alternar Visão
                    </button>

                    <div className="flex items-center gap-4 p-4 bg-white/5 rounded-[2rem] border border-white/5">
                        <div className="sidebar-user-avatar border-2 border-primary/20 rounded-full p-0.5">
                            {renderAvatarContent()}
                        </div>
                        <div className="overflow-hidden">
                            <p className="text-white text-sm font-bold truncate leading-none mb-1">{currentUser.name}</p>
                            <p className="text-[9px] text-white/40 uppercase font-black tracking-widest leading-none">{currentUser.role === 'admin' ? 'Administrador' : 'Vendedor'}</p>
                        </div>
                    </div>

                    <button className="flex items-center justify-center gap-2 w-full py-2 text-white/20 hover:text-error transition-all font-bold text-[10px] uppercase tracking-widest">
                        <LogOut size={16} />
                        <span>Sair</span>
                    </button>
                </div>
            </aside>

            {/* Mobile Toggle Trigger */}
            {!isOpen && (
                <button
                    onClick={toggleSidebar}
                    className="lg:hidden fixed bottom-6 right-6 z-50 size-14 bg-primary text-on-primary rounded-2xl shadow-m3-3 flex items-center justify-center hover:scale-110 active:scale-95 transition-all"
                >
                    <LayoutDashboard size={24} />
                </button>
            )}
        </>
    );
}
